# VMA of .rodata section starts at 0x6b4000, file offset 0x2b4000
# So VMA = file_offset - 0x2b4000 + 0x6b4000 = file_offset + 0x400000
echo 'ncs file_offset 0x'$(printf '%x' 3433227)
