# ncs %s listening on %s is at file 0x350661, VMA = 0x750661
echo 'VMA of ncs string: 0x'$(printf '%x' $((0x350661 + 0x400000)))
objdump -d /input/target 2>/dev/null | grep -B20 '750661\|0x750661' | head -40

